import RNA, random, multiprocessing as mp, time, sys
target = "((..(((..((((..((....((..((((....))....))..))))..))....))..))((..((..((..((((..((....((..((((..((....((....))))..))....))..))))..))((..((..((....))((..((((..((....((..((((....))....))..))))..))....))..))))..))..))..))((..((....((..((((..((....((....))))..))....))..))))..))))..))..)..))"
n=len(target)
# build template init to seed inverse_fold (better than random)
pt=[-1]*n; stk=[]
for i,c in enumerate(target):
    if c=='(': stk.append(i)
    elif c==')':
        j=stk.pop(); pt[i]=j; pt[j]=i
tmpl=['A']*n
for i in range(n):
    if pt[i]!=-1 and i<pt[i]: tmpl[i]='G'; tmpl[pt[i]]='C'
tmpl=''.join(tmpl)
def worker(seed):
    random.seed(seed)
    for _ in range(30):
        # seed = mostly template with some mutations
        if seed%2==0:
            start=list(tmpl)
            for _ in range(random.randint(5,30)):
                i=random.randrange(n)
                start[i]=random.choice('ACGU')
            start=''.join(start)
        else:
            start=''.join(random.choice('ACGU') for _ in range(n))
        seq, d = RNA.inverse_fold(start, target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return seq
    return None
if __name__=='__main__':
    t0=time.time()
    with mp.Pool(120) as p:
        for r in p.imap_unordered(worker, range(600)):
            if r:
                print("SOLVED", r, flush=True); p.terminate(); sys.exit(0)
    print("NONE elapsed", time.time()-t0, flush=True)
